/**
 * yarn.lock, both formats, as the pinned packages OSV is asked about.
 */

import { describe, expect, it } from "vitest";
import { parseYarnLock } from "./yarn-lock.ts";

describe("parseYarnLock", () => {
  it("reads a classic v1 lockfile, scoped names and multi-descriptor entries included", () => {
    const v1 = [
      "# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.",
      "# yarn lockfile v1",
      "",
      "",
      '"@openzeppelin/contracts@4.9.6":',
      '  version "4.9.6"',
      '  resolved "https://registry.yarnpkg.com/@openzeppelin/contracts/-/contracts-4.9.6.tgz"',
      "",
      '"@babel/code-frame@^7.0.0", "@babel/code-frame@^7.10.4":',
      '  version "7.22.13"',
      "  dependencies:",
      '    chalk "^2.4.2"',
      "",
      "chalk@^2.4.2:",
      '  version "2.4.2"',
    ].join("\n");
    expect(parseYarnLock(v1)).toStrictEqual([
      { name: "@openzeppelin/contracts", version: "4.9.6" },
      { name: "@babel/code-frame", version: "7.22.13" },
      { name: "chalk", version: "2.4.2" },
    ]);
  });

  it("reads a berry lockfile and skips the project's own workspace", () => {
    const berry = [
      "__metadata:",
      "  version: 8",
      "  cacheKey: 10c0",
      "",
      '"@openzeppelin/hardhat-upgrades@npm:3.0.5":',
      "  version: 3.0.5",
      '  resolution: "@openzeppelin/hardhat-upgrades@npm:3.0.5"',
      "",
      '"my-app@workspace:.":',
      "  version: 0.0.0-use.local",
    ].join("\n");
    expect(parseYarnLock(berry)).toStrictEqual([{ name: "@openzeppelin/hardhat-upgrades", version: "3.0.5" }]);
  });

  it("refuses text that is not a yarn lockfile, rather than calling it empty", () => {
    expect(parseYarnLock('{"lockfileVersion": 3}')).toBeUndefined();
  });
});
